// Insert inserts the record into the database
func (t *FAPostingTypeSetup) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAPostingTypeSetupTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Fa_posting_type,
		t.Depreciation_book_code,
		t.Part_of_book_value,
		t.Part_of_depreciable_basis,
		t.Include_in_depr_calculation,
		t.Include_in_gain_loss_calc,
		t.Reverse_before_disposal,
		t.Sign,
		t.Depreciation_type,
		t.Acquisition_type,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (fa_posting_type, depreciation_book_code, part_of_book_value, part_of_depreciable_basis, include_in_depr_calculation, include_in_gain_loss_calc, reverse_before_disposal, sign, depreciation_type, acquisition_type) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (fa_posting_type, depreciation_book_code) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert FA_Posting_Type_Setup: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(FAPostingTypeSetupTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *FAPostingTypeSetup) InsertAll(records []*FAPostingTypeSetup, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Fa_posting_type,
			r.Depreciation_book_code,
			r.Part_of_book_value,
			r.Part_of_depreciable_basis,
			r.Include_in_depr_calculation,
			r.Include_in_gain_loss_calc,
			r.Reverse_before_disposal,
			r.Sign,
			r.Depreciation_type,
			r.Acquisition_type,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAPostingTypeSetupTableName)
	columns := []string{"fa_posting_type", "depreciation_book_code", "part_of_book_value", "part_of_depreciable_basis", "include_in_depr_calculation", "include_in_gain_loss_calc", "reverse_before_disposal", "sign", "depreciation_type", "acquisition_type"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *FAPostingTypeSetup) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("fa_posting_type") {
			keyChanged = true
		}
		if t.hasFieldChanged("depreciation_book_code") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, FAPostingTypeSetupTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("fa_posting_type") {
			setClauses = append(setClauses, "fa_posting_type = ?")
			values = append(values, t.Fa_posting_type)
		}
		if t.hasFieldChanged("depreciation_book_code") {
			setClauses = append(setClauses, "depreciation_book_code = ?")
			values = append(values, t.Depreciation_book_code)
		}
		if t.hasFieldChanged("part_of_book_value") {
			setClauses = append(setClauses, "part_of_book_value = ?")
			values = append(values, t.Part_of_book_value)
		}
		if t.hasFieldChanged("part_of_depreciable_basis") {
			setClauses = append(setClauses, "part_of_depreciable_basis = ?")
			values = append(values, t.Part_of_depreciable_basis)
		}
		if t.hasFieldChanged("include_in_depr_calculation") {
			setClauses = append(setClauses, "include_in_depr_calculation = ?")
			values = append(values, t.Include_in_depr_calculation)
		}
		if t.hasFieldChanged("include_in_gain_loss_calc") {
			setClauses = append(setClauses, "include_in_gain_loss_calc = ?")
			values = append(values, t.Include_in_gain_loss_calc)
		}
		if t.hasFieldChanged("reverse_before_disposal") {
			setClauses = append(setClauses, "reverse_before_disposal = ?")
			values = append(values, t.Reverse_before_disposal)
		}
		if t.hasFieldChanged("sign") {
			setClauses = append(setClauses, "sign = ?")
			values = append(values, t.Sign)
		}
		if t.hasFieldChanged("depreciation_type") {
			setClauses = append(setClauses, "depreciation_type = ?")
			values = append(values, t.Depreciation_type)
		}
		if t.hasFieldChanged("acquisition_type") {
			setClauses = append(setClauses, "acquisition_type = ?")
			values = append(values, t.Acquisition_type)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "part_of_book_value = ?")
		values = append(values, t.Part_of_book_value)
		setClauses = append(setClauses, "part_of_depreciable_basis = ?")
		values = append(values, t.Part_of_depreciable_basis)
		setClauses = append(setClauses, "include_in_depr_calculation = ?")
		values = append(values, t.Include_in_depr_calculation)
		setClauses = append(setClauses, "include_in_gain_loss_calc = ?")
		values = append(values, t.Include_in_gain_loss_calc)
		setClauses = append(setClauses, "reverse_before_disposal = ?")
		values = append(values, t.Reverse_before_disposal)
		setClauses = append(setClauses, "sign = ?")
		values = append(values, t.Sign)
		setClauses = append(setClauses, "depreciation_type = ?")
		values = append(values, t.Depreciation_type)
		setClauses = append(setClauses, "acquisition_type = ?")
		values = append(values, t.Acquisition_type)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["fa_posting_type"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Fa_posting_type)
	}
	if old, ok := t.oldValues["depreciation_book_code"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Depreciation_book_code)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND fa_posting_type = ? AND depreciation_book_code = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify FA_Posting_Type_Setup: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

